CREATE TYPE "public"."spot_status" AS ENUM (
    'ALLOWED',
    'TOLERATED',
    'FORBIDDEN',
    'UNCLEAR'
);


ALTER TYPE "public"."spot_status" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_profile_email"("profile_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  user_email TEXT;
BEGIN
  SELECT email INTO user_email FROM auth.users WHERE id = profile_id;
  RETURN user_email;
END;
$$;


ALTER FUNCTION "public"."get_profile_email"("profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.profiles (id)
  values (new.id);
  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_spot_stats"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update public.spots
  set 
    average_rating = (select avg(rating)::numeric(2,1) from spot_verifications where spot_id = new.spot_id and rating is not null),
    rating_count = (select count(*) from spot_verifications where spot_id = new.spot_id and rating is not null),
    last_verified_at = now()
  where id = new.spot_id;
  return new;
end;
$$;


ALTER FUNCTION "public"."update_spot_stats"() OWNER TO "postgres";

