CREATE POLICY "Answer likes viewable by everyone." ON "public"."spot_answer_likes" FOR SELECT USING (true);



CREATE POLICY "Answers viewable by everyone." ON "public"."spot_answers" FOR SELECT USING (true);



CREATE POLICY "Anyone can insert spot deletions" ON "public"."spot_deletions" FOR INSERT WITH CHECK (true);



CREATE POLICY "Authenticated Insert" ON "public"."spot_photos" FOR INSERT WITH CHECK (("auth"."role"() = 'authenticated'::"text"));



CREATE POLICY "Authenticated users can create spot visits." ON "public"."spot_visits" FOR INSERT WITH CHECK ((("auth"."role"() = 'authenticated'::"text") AND ("auth"."uid"() = "user_id")));



CREATE POLICY "Authenticated users can create spots" ON "public"."spots" FOR INSERT WITH CHECK (("auth"."role"() = 'authenticated'::"text"));



CREATE POLICY "Authenticated users can join visits." ON "public"."visit_participants" FOR INSERT WITH CHECK ((("auth"."role"() = 'authenticated'::"text") AND ("auth"."uid"() = "user_id")));



