CREATE POLICY "Authenticated users can review" ON "public"."spot_verifications" FOR INSERT WITH CHECK (("auth"."role"() = 'authenticated'::"text"));



CREATE POLICY "Authenticated users can suggest edits" ON "public"."spots" FOR UPDATE USING (("auth"."role"() = 'authenticated'::"text")) WITH CHECK (("auth"."role"() = 'authenticated'::"text"));



CREATE POLICY "Author or profile owner can delete replies." ON "public"."profile_review_replies" FOR DELETE USING (("auth"."uid"() = "author_id"));



CREATE POLICY "Author or profile owner can delete reviews." ON "public"."profile_reviews" FOR DELETE USING ((("auth"."uid"() = "author_id") OR ("auth"."uid"() = "target_profile_id")));



