CREATE POLICY "Users can like answers." ON "public"."spot_answer_likes" FOR INSERT WITH CHECK ((("auth"."role"() = 'authenticated'::"text") AND ("auth"."uid"() = "user_id")));



CREATE POLICY "Users can like profiles." ON "public"."profile_likes" FOR INSERT WITH CHECK ((("auth"."role"() = 'authenticated'::"text") AND ("auth"."uid"() = "liker_id")));



CREATE POLICY "Users can like questions." ON "public"."spot_question_likes" FOR INSERT WITH CHECK ((("auth"."role"() = 'authenticated'::"text") AND ("auth"."uid"() = "user_id")));



CREATE POLICY "Users can like spots." ON "public"."spot_likes" FOR INSERT WITH CHECK ((("auth"."role"() = 'authenticated'::"text") AND ("auth"."uid"() = "user_id")));



CREATE POLICY "Users can reply to reviews." ON "public"."profile_review_replies" FOR INSERT WITH CHECK ((("auth"."role"() = 'authenticated'::"text") AND ("auth"."uid"() = "author_id")));



CREATE POLICY "Users can review profiles." ON "public"."profile_reviews" FOR INSERT WITH CHECK ((("auth"."role"() = 'authenticated'::"text") AND ("auth"."uid"() = "author_id")));



CREATE POLICY "Users can unbookmark spots." ON "public"."spot_bookmarks" FOR DELETE USING (("auth"."uid"() = "user_id"));



CREATE POLICY "Users can unlike answers." ON "public"."spot_answer_likes" FOR DELETE USING (("auth"."uid"() = "user_id"));



CREATE POLICY "Users can unlike profiles." ON "public"."profile_likes" FOR DELETE USING (("auth"."uid"() = "liker_id"));



CREATE POLICY "Users can unlike questions." ON "public"."spot_question_likes" FOR DELETE USING (("auth"."uid"() = "user_id"));



CREATE POLICY "Users can unlike spots." ON "public"."spot_likes" FOR DELETE USING (("auth"."uid"() = "user_id"));



CREATE POLICY "Users can update their own participant status." ON "public"."visit_participants" FOR UPDATE USING (("auth"."uid"() = "user_id"));



CREATE POLICY "Users can view own bookmarks." ON "public"."spot_bookmarks" FOR SELECT USING (("auth"."uid"() = "user_id"));



CREATE POLICY "Users can view their own spot deletions." ON "public"."spot_deletions" FOR SELECT USING (("auth"."uid"() = "user_id"));



CREATE POLICY "Visit comments are viewable by everyone." ON "public"."visit_comments" FOR SELECT USING (true);



CREATE POLICY "Visit participants are viewable by everyone." ON "public"."visit_participants" FOR SELECT USING (true);



